/* Purpose: public API of RYB Comms, the 13-bit packet link between the four RYB modules.
 * Owning module: management (mgmt/). Protocol: include/ryb/RYB_Comms_Protocol_Guideline.txt. */

#ifndef RYB_COMMS_H
#define RYB_COMMS_H

#include <stdint.h>

#include "ryb/ryb_packet.h"
/* Generated by CMake from ryb_comms.json for the module being built. It holds this module's
 * address, pins and timing, and declares the receive callbacks the module must define. */
#include "ryb/ryb_comms_config.h"

/* Map the GPIO, set up the pins and start the bit loop thread. Needs root for /dev/mem. */
ryb_status_t ryb_comms_init(void);

/* Stop the bit loop and release the line. Safe to call twice; also registered with atexit().
 * If the module installs its own SIGINT/SIGTERM handler, call this from it: a process killed
 * mid-packet otherwise leaves an open-drain lane pulled low for every board on it. */
void ryb_comms_shutdown(void);

/* Hand every packet received since the last call to this module's receive callbacks, on the
 * calling thread, and return how many were delivered. Call it from the main loop; between calls
 * the bit loop keeps receiving, so a slow LCD refresh does not cost packets until the queue fills.
 */
int ryb_comms_poll(void);

/* Queue a packet from this module for transmission; the bit loop clocks it out in the
 * background. Only the decision module sends command packets, so each build declares exactly
 * one of these two. RYB_ERR_BUSY means packets are being queued faster than the line carries
 * them; RYB_ERR_STATE means ryb_comms.json gives this module no "tx" pin. Call from one thread. */
#if RYB_CFG_IS_COMMAND_SENDER
ryb_status_t ryb_send_command(uint16_t first, uint16_t second);
#else
ryb_status_t ryb_send_appended(uint8_t data, ryb_trend_t trend);
#endif

typedef struct {
    uint32_t rx_packets;        /* valid packets queued for the callbacks                    */
    uint32_t rx_parity_errors;  /* frames whose 13 bits did not XOR to 0                     */
    uint32_t rx_address_errors; /* frames from a sender not expected on that link            */
    uint32_t rx_trend_errors;   /* appended packets carrying the reserved trend 11           */
    uint32_t rx_overflows;      /* valid packets lost because ryb_comms_poll() fell behind   */
    uint32_t tx_packets;        /* packets fully clocked out, forwarded ones included        */
    uint32_t tx_overflows;      /* sends or forwards refused because the TX queue was full   */
    uint32_t forwarded;         /* packets a repeater queued for retransmission              */
} ryb_comms_stats_t;

/* Counters since the program started. Rising parity errors usually mean the bit period is too
 * short for the boards' timing jitter, or the lane has no pull-up. */
void ryb_comms_get_stats(ryb_comms_stats_t* out);

typedef struct {
    uint32_t count;      /* packets so far                                  */
    uint64_t t_last_ns;  /* CLOCK_MONOTONIC time of the last one; 0 = none  */
    uint16_t frame;      /* the last one as its 13 wire bits                */
    ryb_packet_t packet; /* the last one decoded                            */
} ryb_comms_sender_t;

/* The last packet seen from `address`, as handed to the callbacks by ryb_comms_poll(). Under
 * this module's own address it is the last packet it queued for sending. For the LCD; call it
 * from the thread that polls. */
void ryb_comms_get_sender(uint8_t address, ryb_comms_sender_t* out);

#endif /* RYB_COMMS_H */
